-- English versions of the halal certifier sheets and religious guides (column en, same shape as the
-- French fields it overrides). Quran: Saheeh International (quran.com 20); hadith: fawazahmed0 English;
-- scholars, Companions and summaries translated with AI help (labelled in the app).
alter table public.halal_certification_bodies add column if not exists en jsonb;
alter table public.halal_religious_guides add column if not exists en jsonb;

update public.halal_certification_bodies set en = $j${"country": "France", "bodyType": "Association", "summary": "Documented certifier: Achahada publishes its specifications (slaughter without stunning or electronarcosis, daily inspection) and its traceability system. No general warning is included.", "facts": {"controlMethod": {"value": "Daily inspection, 7 days a week, by an agent."}, "partners": {"value": "Recognises inspections by Muslim associations that meet the same specifications."}, "slaughterMethod": {"value": "Ritual slaughter by a practising Muslim, cutting the larynx, the jugular veins and the carotid arteries."}, "stunningPolicy": {"value": "Slaughter without prior stunning; no electronarcosis before or after bleeding, and no electric shock after bleeding."}, "traceability": {"value": "Stamps, tags, cable ties, ribbons and labels bearing the Achahada mark; food-grade ink with traceability codes and shapes changed every week; digital tools (QR code)."}}, "criteria": {"noMSM": {"value": "Specifications: no MSM (mechanically separated meat)."}, "noStunning": {"value": "No prior stunning and no electronarcosis before or after bleeding."}, "permanentControl": {"value": "Daily inspection, 7 days a week; slaughter is done by an officer of the association or under its control. Continuous presence along the whole line is not specified."}, "slaughterer": {"value": "Slaughter carried out by a practising Muslim of sound mind."}, "tasmiya": {"value": "The basmala is said by the slaughter officer, before bleeding, over each animal."}, "traceability": {"value": "Trays are labelled by the inspectors; no stamping equipment is left on site without them."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'achahada';
update public.halal_certification_bodies set en = $j${"country": "France", "bodyType": "Association attached to the Grand Mosque of Lyon", "summary": "Documented certifier: the Grand Mosque of Lyon is approved by the French State to authorise ritual slaughterers (order of 27 June 1996) and ARGML publishes its inspection method. No warning documented by a primary source is included.", "facts": {"controlMethod": {"value": "Nearly 80 ritual inspectors; one or more ritual slaughter inspectors present at all times up to final packaging."}, "legalForm": {"value": "Independent non-profit organisation, created in 1995 by the Grand Mosque of Lyon."}, "officialApproval": {"value": "The Grand Mosque of Lyon (Ritual Association of the Grand Mosque of Lyon) is approved as a religious body authorising ritual slaughterers."}, "scope": {"value": "Meat, meat products, ready meals, processed products, cosmetics, restaurants and butchers."}}, "criteria": {"ingredients": {"value": "Checks on ingredients, additives, processing aids, gelatines and alcohol in processed products."}, "noStunning": {"value": "Cattle: ritual slaughter “guaranteed without stunning before or after death”. Poultry: the page consulted describes electronarcosis without stating the rule the certifier applies."}, "permanentControl": {"value": "Ritual inspectors employed by the association, assigned to the sites at all times during halal production, from slaughter to final packaging."}, "traceability": {"value": "Raw meat arrives under ARGML seal so that traceability is never broken."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'argml';
update public.halal_certification_bodies set en = $j${"country": "France", "bodyType": "Non-profit association (1901 law)", "summary": "Documented certifier: AVS publishes its method on its official website (inspectors present at all times, refusal of any stunning). No warning documented by a primary source is included.", "facts": {"controlMethod": {"value": "Permanent, continuous presence of inspectors at all production sites; over a hundred employees, 80% of them dedicated to inspection."}, "legalForm": {"value": "Non-profit association (1901 law), created in 1991, based in Saint-Denis (93)."}, "scope": {"value": "Halal inspection and certification for butchers, restaurants and brands in mainland France."}, "stunningPolicy": {"value": "No stunning method accepted, for all animals slaughtered under its control (sheep, cattle, poultry); refuses to certify meat from a stunned animal."}, "traceability": {"value": "Inspectors present from slaughter to packaging and sealing; personalised certification equipment, regularly renewed and always kept by the inspectors."}}, "criteria": {"noStunning": {"value": "No stunning process accepted, for all animals (sheep, cattle, poultry); the certifier guarantees that the animal is alive when its throat is cut."}, "permanentControl": {"value": "Permanent, continuous presence of inspectors at all production and processing sites; no certification without them."}, "traceability": {"value": "Inspectors present from slaughter to packaging; personalised certification equipment, always kept by the inspectors."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'avs';
update public.halal_certification_bodies set en = $j${"country": "Thailand", "summary": "Certifier to check: the official regulation consulted (R-CICOT-01) requires a traceability system, but does not detail the slaughter rules (slaughterer, stunning, inspection).", "facts": {}, "criteria": {"traceability": {"value": "Certified companies must have a traceability system (production date and place, batch, certificate…) (9.6)."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'cicot';
update public.halal_certification_bodies set en = $j${"country": "Germany", "summary": "Documented certifier: EHZ (Hamburg) publishes its halal guidelines. It requires a Muslim slaughterer and the invocation, but accepts stunning where slaughter without stunning is not permitted, mechanical poultry slaughter, and sites that also handle non-halal products (after cleaning).", "facts": {}, "criteria": {"ingredients": {"value": "Ingredients, additives and colours must comply; independent laboratory tests if needed (5 and 5.4.7)."}, "manualSlaughter": {"value": "Mechanical poultry slaughter is accepted; birds missed by the machine are slaughtered by hand by Muslims (5.1.7)."}, "noPork": {"value": "Machines used for non-halal animals may be used after cleaning; separate lines required, or case-by-case arrangements (5.1.12 and 5.4.2)."}, "noStunning": {"value": "Slaughter without stunning is preferred “if possible and permitted”; otherwise stunning (electric, or gas for poultry) is applied, and the animal must not die before bleeding (5.1.4-5.1.5 and annex)."}, "slaughterer": {"value": "Slaughter must be done by Muslim slaughterers (5.1.2)."}, "tasmiya": {"value": "The name of Allah must be said over each animal (5.1.6); in mechanical poultry slaughter, by a Muslim when the machine is started, at every restart (5.1.7)."}, "traceability": {"value": "Supervision “without interruption from raw material to finished product”; the meat's veterinary numbers are checked against the certificate (5 and 5.4.1)."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'ehz';
update public.halal_certification_bodies set en = $j${"summary": "Documented certifier: EHZ (Hamburg) publishes its halal guidelines. It requires a Muslim slaughterer and the invocation, but accepts stunning where slaughter without stunning is not permitted, mechanical poultry slaughter, and sites that also handle non-halal products (after cleaning).", "facts": {}, "criteria": {"ingredients": {"value": "Ingredients, additives and colours must comply; independent laboratory tests if needed (5 and 5.4.7)."}, "manualSlaughter": {"value": "Mechanical poultry slaughter is accepted; birds missed by the machine are slaughtered by hand by Muslims (5.1.7)."}, "noPork": {"value": "Machines used for non-halal animals may be used after cleaning; separate lines required, or case-by-case arrangements (5.1.12 and 5.4.2)."}, "noStunning": {"value": "Slaughter without stunning is preferred “if possible and permitted”; otherwise stunning (electric, or gas for poultry) is applied, and the animal must not die before bleeding (5.1.4-5.1.5 and annex)."}, "slaughterer": {"value": "Slaughter must be done by Muslim slaughterers (5.1.2)."}, "tasmiya": {"value": "The name of Allah must be said over each animal (5.1.6); in mechanical poultry slaughter, by a Muslim when the machine is started, at every restart (5.1.7)."}, "traceability": {"value": "Supervision “without interruption from raw material to finished product”; the meat's veterinary numbers are checked against the certificate (5 and 5.4.1)."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'eurohalal';
update public.halal_certification_bodies set en = $j${"country": "France", "bodyType": "Mosque (own certification)", "summary": "Certifier to check: since 2022, the Grand Mosque of Paris has issued its own certification and states that its inspectors oversee every production stage. It does not publish its rule on stunning or the details of its specifications.", "facts": {"partners": {"value": "Partnership with SFCVH ended on 1 June 2022; its own certification with an exclusive logo since then."}, "scope": {"value": "Specifications and halal certification code for food industry products."}}, "criteria": {"permanentControl": {"value": "“At every stage of production, GMP inspectors make sure procedures are followed”; continuous presence is not specified."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'grande-mosquee-de-paris';
update public.halal_certification_bodies set en = $j${"country": "France", "summary": "Not enough information: the certifier publishes neither its rule on stunning nor its inspection method, and no identifiable source documents them. No criterion is therefore publicly guaranteed.", "facts": {}, "criteria": {}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'halal-services';
update public.halal_certification_bodies set en = $j${"country": "United Kingdom", "summary": "Certifier to check: according to its 2014 statement, HFA accepts electric water-bath stunning of poultry (non-lethal settings), under the supervision of its representatives.", "facts": {}, "criteria": {"noStunning": {"value": "Electric water-bath stunning of poultry accepted (1000 Hz minimum, 205 mA maximum per bird)."}, "permanentControl": {"value": "Halal stunning and slaughter of poultry only take place in the presence and under the supervision of HFA representatives."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'hfa-uk';
update public.halal_certification_bodies set en = $j${"country": "Belgium", "bodyType": "Certification body", "summary": "Not enough information: the certifier publishes neither its rule on stunning nor its inspection method, and no identifiable source documents them. No criterion is therefore publicly guaranteed.", "facts": {"legalForm": {"value": "Body founded in 2010, with offices and affiliates in Europe including France."}}, "criteria": {}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'hfce';
update public.halal_certification_bodies set en = $j${"country": "France (HQC Europe office)", "bodyType": "Private certification body", "summary": "Caution advised on the scope of accreditations: HQC France's EIAC accreditation is confirmed by the French Treasury (DG Trésor) for meat and meat products exported to the United Arab Emirates. The other accreditations shown (IAF, IHAF) come without their scope. A product's certification should therefore be checked in context (country, office, type of product).", "facts": {"accreditation": {"value": "EIAC (Emirates International Accreditation Center) accreditation for halal certification of meat and meat products exported to the United Arab Emirates."}, "legalForm": {"value": "Halal certification body that describes itself as approved and independent, founded in 1983; French office in Paris."}, "partners": {"value": "Member of the World Halal Food Council (WHFC); IAF and IHAF accreditations claimed without stating their scope."}, "scope": {"value": "Food, cosmetics, pharmaceuticals and services."}}, "criteria": {"permanentControl": {"value": "The certifier describes inspection by audit: an auditor visits the company and assesses its procedures, followed by “regular audits”. No permanent presence is announced."}, "traceability": {"value": "Approach described as “covering all aspects, including traceability”, without details of the system."}}, "warnings": [{"title": "Exact scope of accreditations to check", "summary": "The accreditation confirmed by an institution (French Treasury, 07/05/2025) covers meat and meat products exported to the United Arab Emirates. The other accreditations shown by the certifier do not state their scope: they should not be read as a general guarantee.", "scope": "Accreditations and recognition claimed", "issuedBy": "OUMMAH, based on the French Treasury and the certifier's website"}], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'hqc-france';
update public.halal_certification_bodies set en = $j${"country": "North America", "summary": "Documented certifier: IFANCA publishes a five-star system. A Muslim slaughterer and the invocation over each animal are required; no stunning and fully manual slaughter are only guaranteed for products carrying the matching star.", "facts": {}, "criteria": {"manualSlaughter": {"value": "Traditional manual slaughter for the second star; mechanical slaughter accepted for poultry."}, "noStunning": {"value": "Only guaranteed for “five-star” products; IFANCA also certifies red-meat slaughterhouses that stun."}, "slaughterer": {"value": "Muslim slaughterers only; IFANCA neither certifies nor accepts meat slaughtered by non-Muslims."}, "tasmiya": {"value": "Tasmiya and takbir over each animal at the moment of slaughter; in mechanical poultry slaughter, by a Muslim when the machine is started, with a Muslim on the line."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'ifanca';
update public.halal_certification_bodies set en = $j${"country": "Malaysia", "summary": "Documented certifier (Malaysian public authority): the official protocol permits reversible stunning; it requires a Muslim slaughterer, the invocation, a Muslim halal inspector in the slaughter hall, and bans all pork products from the premises.", "facts": {}, "criteria": {"noPork": {"value": "No pork or dog products are allowed in an approved establishment; non-halal products are banned there (4.2.2-4.2.3)."}, "noStunning": {"value": "Stunning permitted “if used”, provided it is reversible and does not kill; animals that die from stunning are removed (4.5.1)."}, "permanentControl": {"value": "A Muslim halal inspector must be present in the slaughter hall (stunning, cutting, bleeding), plus a Muslim halal supervisor (4.5.4)."}, "slaughterer": {"value": "Muslim slaughterer registered, trained and supervised by the certification body (5.3)."}, "tasmiya": {"value": "The tasmiya is said by the Muslim slaughterer just before the cut (4.5.2 f)."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'jakim';
update public.halal_certification_bodies set en = $j${"country": "France", "bodyType": "Approved mosque (religious body)", "summary": "Certifier to check: the Évry mosque is approved by the French State to authorise slaughterers, but does not publish its inspection method. According to the ASIDCOM survey (December 2009), stunning before bleeding was liable to be practised and the inspectors were employed by the slaughterhouses. Old information that the certifier has not publicly updated.", "facts": {"officialApproval": {"value": "The Évry mosque (Association of Muslims of Île-de-France) is approved as a religious body authorising ritual slaughterers."}}, "criteria": {"noStunning": {"value": "Stunning before bleeding “liable to be practised” according to the charter the certifier published at the time. Information from 2009."}, "permanentControl": {"value": "Inspectors employed by the slaughterhouses; no independent, permanent inspection. Information from 2009."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'mosquee-evry';
update public.halal_certification_bodies set en = $j${"country": "Singapore", "summary": "Certifier to check: the only available version of the MUIS-HC-S001 standard is a draft (2005). It requires a Muslim and the basmala, and accepts automatic slaughter; it does not state the rule on stunning.", "facts": {}, "criteria": {"manualSlaughter": {"value": "Automatic slaughter is accepted, with a check that the animals are alive before the cut (B.4.2 d)."}, "slaughterer": {"value": "Manual slaughter by a Muslim; in automatic slaughter, the person who starts the machine must be Muslim (B.3.2)."}, "tasmiya": {"value": "The slaughterer, or the person who starts the machine, recites the basmala (B.4.2)."}}, "warnings": [], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'muis';
update public.halal_certification_bodies set en = $j${"country": "France", "bodyType": "Company", "summary": "Certifier to check: the official website does not publish its method. According to the survey by the consumer association ASIDCOM (December 2009), which quotes the charter the certifier published at the time, stunning before bleeding was liable to be practised and the inspectors were employed by the slaughterhouses. Old information that the certifier has not publicly updated. The partnership with the Grand Mosque of Paris ended on 1 June 2022.", "facts": {"scope": {"value": "Inspection of halal meat and its derivatives, and of food industry products."}}, "criteria": {"ingredients": {"value": "Inspection covers food products to identify any non-compliant substance or additive."}, "noStunning": {"value": "Stunning before bleeding “liable to be practised” according to the charter the certifier published at the time, and used for poultry according to the certification indicators quoted in the survey. Information from 2009."}, "permanentControl": {"value": "Inspectors employed by the slaughterhouses; no independent inspection. Information from 2009."}}, "warnings": [{"title": "End of the partnership with the Grand Mosque of Paris (1 June 2022)", "summary": "The Grand Mosque of Paris states that its halal certification partnership with SFCVH ended on 1 June 2022 and that the shared logo is no longer valid. The statement makes no criticism of SFCVH. Historical information: it concerns the former shared logo, not current SFCVH certifications.", "scope": "Former shared Grand Mosque of Paris / SFCVH logo", "issuedBy": "Grand Mosque of Paris"}], "criticisms": [], "scholarlyNotes": []}$j$::jsonb where id = 'sfcvh';
update public.halal_religious_guides set en = $j${"title": "Stunning / electronarcosis", "question": "Is an animal stunned before slaughter lawful?", "quran": [{"reference": "Al-Ma’idah 5:3", "text": "Meaning: “Prohibited to you are dead animals, blood, the flesh of swine, […] and [those animals] killed by strangling or by a violent blow […], except what you [are able to] slaughter [before its death].” (Saheeh International)"}], "sunnah": [{"reference": "Muslim 1955 (Shaddad ibn Aws)", "text": "“Verily Allah has enjoined goodness to everything; […] when you slaughter, slaughter in a good way. So every one of you should sharpen his knife, and let the slaughtered animal die comfortably.”"}], "companions": [{"name": "‘Abdullah ibn ‘Umar", "reference": "Reported by Al-Bukhari (ta‘liq), Book of Slaughtering and Hunting, chapter on game killed by the side of the arrow", "text": "About game killed by a pellet (al-bunduqa): “That is the mawqudhah” (the animal killed by a blow)."}], "scholars": [{"scholar": "Ibn Baz", "reference": "Majmu‘ Fatawa Ibn Baz 8/428 — Al-Islah magazine no. 90, Dhul-Qa‘dah 1405 AH", "position": "An animal that dies from stunning is forbidden (like an animal killed by a blow or by strangling); “what has been stunned or struck, then found alive and slaughtered according to the rule, is lawful”."}, {"scholar": "Permanent Committee (fatwa signed by Ibn Baz)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fatwa no. 1665: if it dies from stunning, the animal is forbidden (reported consensus); if it is reached alive and slaughtered, it is lawful. Stunning itself is forbidden because it makes the animal suffer, unless it cannot be slaughtered any other way."}, {"scholar": "Permanent Committee (fatwas signed by Al-Fawzan and Ibn Baz)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fatwa no. 18476: stunned and then slaughtered alive, the animal is lawful; if it dies from stunning, it is forbidden. Fatwa no. 17924: anaesthesia before slaughter is not permitted because it can kill the animal; if it is slaughtered alive, it remains lawful."}, {"scholar": "Ibn ‘Uthaymin", "reference": "Majmu‘ Fatawa wa Rasa’il 15/442 (question 1182); Fatawa Nur ‘ala ad-Darb 20/2", "position": "A stunned animal whose blood is made to flow before it dies is lawful. Regarding what is said about foreign slaughterhouses, “scrupulousness (al-wara‘) is to refrain from it”, with no sin on whoever eats it."}, {"scholar": "Al-Albani", "reference": "Fatawa ‘abr al-hatif wa as-sayyarah, tape 152; Silsilat al-Huda wan-Nur, tape 327", "position": "If stunning does not kill and the animal is slaughtered alive, its meat remains lawful; but stunning is a sin because it causes suffering, and no one can guarantee that stunning does not kill. He refused to have Muslims approve as “halal” a poultry line stunned in an electric water bath."}], "agreement": "All agree: an animal that dies from stunning before it is slaughtered is forbidden; an animal stunned and then slaughtered while still alive is lawful.", "divergence": "On the act of stunning: the Permanent Committee forbids it except in necessity and Al-Albani considers it a sin; Ibn ‘Uthaymin does not explicitly condemn it in the texts used. On what to do in case of doubt: scrupulousness recommended (Ibn ‘Uthaymin), abstaining (Al-Albani).", "reading": "A certifier that refuses all stunning removes the risk of an animal dying before slaughter. A certifier that accepts it depends on a guarantee that stunning does not kill, a guarantee several scholars consider hard to give. This alone does not make a product “not halal”."}$j$::jsonb where id = 'stunning';
update public.halal_religious_guides set en = $j${"title": "Invocation at slaughter", "question": "Must the name of Allah be said over each animal, and what happens if it is forgotten?", "quran": [{"reference": "Al-An‘am 6:121", "text": "Meaning: “And do not eat of that upon which the name of Allāh has not been mentioned, for indeed, it is grave disobedience.” (Saheeh International)"}, {"reference": "Al-An‘am 6:118", "text": "Meaning: “So eat of that [meat] upon which the name of Allāh has been mentioned, if you are believers in His verses [i.e., revealed law].” (Saheeh International)"}], "sunnah": [{"reference": "Al-Bukhari and Muslim 1968 (Rafi‘ ibn Khadij)", "text": "“[…] which would let the blood flow (and along with it) the name of Allah is also to be recited. Then eat, but not the tooth or nail.”"}, {"reference": "Al-Bukhari 5507 (‘A’ishah), Book of Slaughtering", "text": "A group of people said to the Prophet, “Some people bring us meat and we do not know whether they have mentioned Allah's Name or not on slaughtering the animal.” He said, “Mention Allah's Name on it and eat.” Those people had embraced Islam recently."}], "companions": [{"name": "‘Abdullah ibn ‘Abbas", "reference": "Reported by Al-Bukhari (ta‘liq), chapter on the invocation over the slaughtered animal and on whoever leaves it out deliberately", "text": "“Whoever forgets, there is no harm.” Al-Bukhari adds: the one who forgets is not called disobedient (fasiq), referring to 6:121."}], "scholars": [{"scholar": "Ibn Baz", "reference": "Nur ‘ala ad-Darb programme", "position": "If it is forgotten, the animal is lawful; the ignorant person is also excused. Leaving it out deliberately, knowing the rule, makes the animal forbidden according to the more correct view."}, {"scholar": "Permanent Committee (fatwas signed by Ibn Baz)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fatwa no. 11490: an animal over which the invocation was forgotten is lawful (view reported from Ibn ‘Abbas). Fatwa no. 11967: the invocation must come from the slaughterer, not from a recording device."}, {"scholar": "Al-Fawzan", "reference": "Al-Mulakhkhas al-Fiqhi 2/591; Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fourth condition of slaughter: the slaughterer says “bismillah” at the moment of the act; the takbir is recommended with it. Permanent Committee, fatwa no. 15666 (signed by Al-Fawzan and Ibn Baz): the invocation is made over each animal; one collective invocation over a herd is not enough."}, {"scholar": "Ibn ‘Uthaymin", "reference": "Al-Sharh al-Mumti‘ 15/86-87", "position": "The invocation is a condition that does not fall away through forgetfulness or ignorance: whoever forgets it has not sinned, but the animal is not eaten. It must be said by the slaughterer himself."}, {"scholar": "Al-Albani", "reference": "Silsilat al-Huda wan-Nur, tapes 131 and 731", "position": "The hadith of ‘A’ishah concerns the invocation, not the method of slaughter: saying “bismillah” while eating does not make lawful an animal that was killed without being slaughtered. Wording: “bismillah”."}], "agreement": "All agree: the invocation is required, said by the slaughterer himself, and neither a recording nor a written basmala replaces it.", "divergence": "On forgetting: the animal remains lawful for Ibn Baz and the Permanent Committee (view of Ibn ‘Abbas); it does not for Ibn ‘Uthaymin. No view of Al-Albani on forgetting was found in a verifiable source.", "reading": "A certifier that states it requires the invocation over each animal meets the shared requirement. This alone does not settle the case of an occasional omission."}$j$::jsonb where id = 'tasmiya';
update public.halal_religious_guides set en = $j${"title": "Conditions for the slaughterer", "question": "Who may slaughter an animal whose meat is lawful?", "quran": [{"reference": "Al-Ma’idah 5:5", "text": "Meaning: “[…] the food of those who were given the Scripture is lawful for you and your food is lawful for them.” (Saheeh International)"}], "sunnah": [{"reference": "Al-Bukhari 391 (Anas ibn Malik)", "text": "“Whoever prays like us and faces our Qibla and eats our slaughtered animals is a Muslim […]”"}], "companions": [{"name": "‘Abdullah ibn ‘Abbas", "reference": "Reported by Al-Bukhari (ta‘liq), chapter on animals slaughtered by the People of the Book", "text": "“Their food: it is their slaughtered animals” (about 5:5)."}], "scholars": [{"scholar": "Al-Fawzan", "reference": "Al-Mulakhkhas al-Fiqhi 2/588-589", "position": "The slaughterer must be of sound mind, Muslim or one of the People of the Book (Jew or Christian). Animals slaughtered by an idolater, a Zoroastrian, an apostate, or someone who calls upon the dead at shrines are not lawful."}, {"scholar": "Ibn ‘Uthaymin", "reference": "Majmu‘ Fatawa wa Rasa’il 15/442 (question 1182); Al-Sharh al-Mumti‘ 15/62-63; Fatawa Nur ‘ala ad-Darb 20/2", "position": "Five cases: one knows, or strongly thinks, that the slaughterer is Muslim or one of the People of the Book: lawful; one doubts, or strongly thinks, or knows that he is not: forbidden. Today's Christians remain People of the Book as long as they claim their religion; there is no need to ask how they slaughtered."}, {"scholar": "Ibn Baz", "reference": "Nur ‘ala ad-Darb programme", "position": "Meat from the lands of the People of the Book: lawful in principle, unless one knows it was killed by strangling or by a blow. Meat from lands without a scripture: forbidden in principle, unless one knows a Muslim or one of the People of the Book slaughtered it."}, {"scholar": "Permanent Committee (fatwa signed by Ibn Baz)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fatwa no. 2340: when animals from slaughterers whose slaughter is valid and others whose slaughter is not are mixed and cannot be told apart, they are all forbidden; it is recommended to choose one's slaughterers oneself."}, {"scholar": "Al-Albani", "reference": "Silsilat al-Huda wan-Nur, tapes 253 and 131", "position": "Two conditions for the meat of the People of the Book: the slaughterer is Jewish or Christian, and the animal is truly slaughtered, not killed. Three cases: one knows it is lawful, one knows it is forbidden, or one does not know, and then “leave what makes you in doubt”."}], "agreement": "All agree: only an animal slaughtered by a Muslim, a Jew or a Christian is lawful; one slaughtered by an idolater, a Zoroastrian or an apostate is not.", "divergence": "On the presumption for meat from Western countries: lawful in principle for Ibn Baz and Ibn ‘Uthaymin (who still recommends scrupulousness); Al-Albani, personally convinced that slaughter there is rarely compliant, advises abstaining in case of doubt.", "reading": "Requiring a Muslim slaughterer goes beyond the shared validity condition (Muslim or People of the Book): it is an extra precaution."}$j$::jsonb where id = 'slaughterer';
update public.halal_religious_guides set en = $j${"title": "Mechanical slaughter", "question": "Can a machine slaughter, and how is the invocation made?", "quran": [], "sunnah": [{"reference": "Al-Bukhari and Muslim 1968 (Rafi‘ ibn Khadij)", "text": "“[…] which would let the blood flow (and along with it) the name of Allah is also to be recited. Then eat […]”"}, {"reference": "Muslim 1955 (Shaddad ibn Aws)", "text": "“So every one of you should sharpen his knife, and let the slaughtered animal die comfortably.”"}], "companions": [{"name": "‘Abdullah ibn ‘Abbas", "reference": "Reported by Al-Bukhari (ta‘liq), chapter on slaughtering", "text": "“Slaughter is done at the throat and the base of the neck (al-halq wa al-labbah).”"}, {"name": "Ibn ‘Umar, Ibn ‘Abbas and Anas ibn Malik", "reference": "Reported by Al-Bukhari (ta‘liq), chapter on slaughtering", "text": "“If the head is cut off, there is no harm.”"}, {"name": "‘Abdullah ibn ‘Umar", "reference": "Reported by Al-Bukhari (ta‘liq), chapter on slaughtering", "text": "He forbade cutting down to the spinal cord (an-nakh‘): “one cuts what is short of the bone, then leaves the animal until it dies” (reported by Nafi‘)."}], "scholars": [{"scholar": "Ibn Baz", "reference": "Fatawa ad-Durus", "position": "Asked about slaughtering with an electric machine: “yes, if it is sharp”."}, {"scholar": "Permanent Committee (fatwas signed by Ibn Baz and/or Al-Fawzan)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "No. 9677 (Ibn Baz): the automatic machine is permitted; a single invocation is enough, said by whoever starts it, if he is Muslim or one of the People of the Book. No. 21165 (Al-Fawzan): the blade must be sharp and cut the windpipe and the oesophagus; in manual slaughter, one invocation per animal. No. 20738 (Al-Fawzan and Ibn Baz): if the machine slaughters batch after batch, one invocation each time it is started; the basmala written on the blade is not enough."}, {"scholar": "Ibn ‘Uthaymin", "reference": "Liqa’ al-Bab al-Maftuh, session no. 35 (recording)", "position": "One invocation over a defined batch is enough (for example a thousand hanging birds, “bismillah” when the machine is started). A single invocation at the start for the whole day is not valid; a basmala written on the wall without being said comes from ignorance."}, {"scholar": "Al-Albani", "reference": "—", "position": "No verifiable view found on the mechanical blade itself; his reservations about automatic lines concern stunning (see the “Stunning” guide)."}], "agreement": "The scholars cited accept the machine if its blade cuts the throat and the invocation is said by a Muslim or one of the People of the Book who starts it.", "divergence": "Minor: Ibn ‘Uthaymin explicitly requires one invocation per defined batch and rejects a single invocation for a whole day.", "reading": "Manual slaughter is not a validity condition; it is a precaution that makes it easier to say the invocation over each animal and to check the cut."}$j$::jsonb where id = 'mechanical';
update public.halal_religious_guides set en = $j${"title": "Contamination and the production line", "question": "What does the rule say about contact with pork and mixing meats?", "quran": [{"reference": "Al-Baqarah 2:173", "text": "Meaning: “He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allāh.” (Saheeh International)"}, {"reference": "Al-An‘am 6:145", "text": "Meaning: “[…] or the flesh of swine - for indeed, it is impure […]” (Saheeh International)"}], "sunnah": [{"reference": "Al-Bukhari and Muslim 1930 (Abu Tha‘labah al-Khushani)", "text": "“[…] if you can get utensils other than theirs, then don't eat in them; but if you do not find any, then wash them and eat in them.”"}, {"reference": "Al-Bukhari 52 and Muslim 1599 (An-Nu‘man ibn Bashir)", "text": "“Both legal and illegal things are evident but in between them there are doubtful (suspicious) things […] So whoever saves himself from these suspicious things saves his religion and his honor.”"}, {"reference": "At-Tirmidhi 2518 (Al-Hasan ibn ‘Ali), graded authentic by Al-Albani", "text": "“Leave what makes you in doubt for what does not make you in doubt.”"}], "companions": [], "scholars": [{"scholar": "Permanent Committee (fatwa signed by Ibn Baz)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fatwa no. 5442: utensils used for pork or wine are only used after being washed. Fatwa no. 2340: meats from valid and invalid slaughter mixed without distinction are all forbidden."}, {"scholar": "Permanent Committee (fatwa signed by Al-Fawzan)", "reference": "Fatawa al-Lajnah ad-Da’imah, 1st series, volume 22", "position": "Fatwa no. 21341: food prepared by non-Muslims is permitted, unless one knows it contains pork or one of its derivatives, or meat not slaughtered according to the rule."}, {"scholar": "Ibn ‘Uthaymin", "reference": "Majmu‘ Fatawa wa Rasa’il 15/441 (question 1181)", "position": "The vessels of non-Muslims are washed before use, even if they are clean, so as to be distinct from them."}, {"scholar": "Al-Albani", "reference": "Sharh al-Adab al-Mufrad, tape 19", "position": "Tinned meat, butter and cheese produced in the West: if one knows they are lawful, one eats them; if one knows they contain forbidden fats, no; if one does not know, one refrains (“leave what makes you in doubt”)."}], "agreement": "Pork and its derivatives are forbidden; a soiled utensil is washed before use; meats from valid and invalid slaughter mixed without distinction are all forbidden.", "divergence": "No fatwa from the scholars cited was found on an industrial line shared between halal and non-halal: OUMMAH draws no conclusion from it.", "reading": "Refusing sites that handle pork, checking ingredients and ensuring traceability are precautions against mixing and contamination; their absence is not, on its own, proof of contamination."}$j$::jsonb where id = 'contamination';
